STYLES_SRC = BASE / 'src' / 'style.css'
OUTPUT_DIR = BASE / 'pegasus'
OUTPUT_HTML = OUTPUT_DIR / 'index.html'
OUTPUT_CSS = OUTPUT_DIR / 'style.css'

